# Lines in PG(3,2): a line through points p and q consists of {p, q, p+q (mod 2)}
# Three points are collinear if their XOR sum is 0 (i.e., p XOR q XOR r = 0)

def xor_vec(a, b):
    return tuple(x ^ y for x, y in zip(a, b))

def is_zero(v):
    return all(x == 0 for x in v)

# Find all lines (triples where p XOR q XOR r = 0)
