for i, j, k in combinations(range(15), 3):
    p, q, r = points[i], points[j], points[k]
    if is_zero(xor_vec(xor_vec(p, q), r)):
        lines.append((i, j, k))

print(f"Number of lines in PG(3,2): {len(lines)}")
print("First few lines:", lines[:5])

# Verify it's a valid STS(15)
# Check each point appears in r=7 blocks
from collections import Counter
point_count = Counter()
for line in lines:
    for p in line:
        point_count[p] += 1
print("Point frequencies:", sorted(point_count.values()))

# Check each pair appears in exactly 1 block
pair_count = Counter()
for line in lines:
    for pair in combinations(line, 2):
        pair_count[pair] += 1
print("Pair frequencies:", sorted(set(pair_count.values())))
print("All pairs covered:", len(pair_count) == 15*14//2)

