from itertools import combinations
from collections import Counter

# Points of PG(3,2): non-zero vectors in GF(2)^4
points = []
for i in range(1, 16):
    vec = tuple((i >> j) & 1 for j in range(4))
    points.append(vec)

def xor_vec(a, b):
    return tuple(x ^ y for x, y in zip(a, b))

def is_zero(v):
    return all(x == 0 for x in v)

# Find all lines (triples where p XOR q XOR r = 0)
lines = []
for i, j, k in combinations(range(15), 3):
    p, q, r = points[i], points[j], points[k]
    if is_zero(xor_vec(xor_vec(p, q), r)):
        lines.append((i, j, k))

# BIBD(15,3,2) = 2 copies of STS(15)
all_blocks = lines + lines  # 70 blocks total
print(f"Total blocks: {len(all_blocks)}")

# Verify BIBD(15,3,2) properties
# 1. Each block has 3 points
print("Block sizes:", set(len(b) for b in all_blocks))

# 2. Each point in r=14 blocks
point_count = Counter()
for block in all_blocks:
    for p in block:
        point_count[p] += 1
print("Point frequencies:", sorted(point_count.values()))

# 3. Each pair in lambda=2 blocks
pair_count = Counter()
for block in all_blocks:
    for pair in combinations(block, 2):
        pair_count[pair] += 1
print("Pair frequencies:", sorted(set(pair_count.values())))
print("All pairs covered:", len(pair_count) == 15*14//2)
